import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/services/auth_service.dart';

class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState()=>_LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen>{ final email=TextEditingController(); final password=TextEditingController(); final phone=TextEditingController(); bool loading=false; String? error;
 @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Column(children:[const Icon(Icons.groups,size:84,color:Colors.green),const Text('Mama Group',style:TextStyle(fontSize:32,fontWeight:FontWeight.bold)),const SizedBox(height:24),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),const SizedBox(height:12),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone login (+255...)')),if(error!=null) Text(error!,style:const TextStyle(color:Colors.red)),const SizedBox(height:16),FilledButton(onPressed:loading?null:() async{setState(()=>loading=true);try{await context.read<AuthService>().signInWithEmail(email.text.trim(),password.text);}catch(e){setState(()=>error=e.toString());} finally{setState(()=>loading=false);}},child:Text(loading?'Please wait...':'Login')),TextButton(onPressed:()=>context.read<AuthService>().resetPassword(email.text.trim()),child:const Text('Forgot password')),OutlinedButton(onPressed:()=>context.read<AuthService>().verifyPhone(phone:phone.text,completed:(_){},failed:(e)=>setState(()=>error=e.message),codeSent:(_,__)=>setState(()=>error='OTP sent. Connect OTP screen for production flow.')),child:const Text('Login with phone number'))])))));}
